def get_modele():
    return io.BytesIO(base64.b64decode(MODELE_B64))


def formater_date(date_str):
    if not date_str:
        return "Non renseigné"
    jours = ["Lundi","Mardi","Mercredi","Jeudi","Vendredi","Samedi","Dimanche"]
    mois = ["janvier","février","mars","avril","mai","juin",
            "juillet","août","septembre","octobre","novembre","décembre"]
    try:
        d = datetime.strptime(str(date_str)[:10], "%Y-%m-%d")
        return jours[d.weekday()] + " " + str(d.day) + " " + mois[d.month-1] + " " + str(d.year)
    except Exception:
        return str(date_str)


def extraire_heure(date_str):
    """Extrait l'heure depuis une date ISO (ex: 2026-07-19T12:30:00.000+02:00 -> 12h30)."""
    if not date_str:
        return "Non renseigné"
    import re as _re
    # Chercher le pattern HH:MM dans la chaîne
    m = _re.search(r'T(\d{2}):(\d{2})', str(date_str))
    if m:
        h, mn = m.group(1), m.group(2)
        return h + "h" + mn
    return "Non renseigné"


def extraire_ville(adresse):
    if not adresse:
        return ""
    parts = str(adresse).split(",")
    if len(parts) >= 2:
        ville = re.sub(r"\d{5}\s+", "", parts[-1].strip())
        return ville.upper()
    return adresse


def clean(txt):
    if not txt or str(txt).strip() in ["-", ""]:
        return "Non renseigné."
    txt = str(txt)
    txt = re.sub(r"\*\*([^*]+)\*\*", r"\1", txt)
    txt = re.sub(r"\*([^*]+)\*", r"\1", txt)
    txt = txt.replace("<br>", " ").replace("<br/>", " ")
    txt = re.sub(r"<[^>]+>", "", txt)
    return txt.strip()


def esc(text):
    s = str(text)
    s = s.replace("&", "&amp;")
    s = s.replace("<", "&lt;")
    s = s.replace(">", "&gt;")
    s = s.replace("'", "&apos;")
    return s


def slugify(s, max_len=20):
    slug = re.sub(r"[^a-zA-Z0-9]+", "-", str(s)).strip("-")
    return slug[:max_len].strip("-")


def construire_nom_base(data, is_final, date_str):
    inter      = data.get("intervention", {})
    site       = data.get("site", {})
    ref        = inter.get("ref", "JG-XX")
    client_nom = data.get("client", "")
    site_nom   = site.get("nom", "")
    client_slug = slugify(client_nom) if client_nom else ""
    site_slug   = slugify(site_nom) if site_nom else ref
    if client_slug and not site_slug.startswith(client_slug[:10]):
        base_nom = client_slug + "_" + site_slug
    else:
        base_nom = site_slug
    prefix = "" if is_final else "BROUILLON_"
    return prefix + "Rapport-Intervention_JetGuards_" + base_nom + "_" + date_str + "_" + ref


def make_para(text, sp=None):
    if sp is None:
        sp = SP_100
    return '<w:p><w:pPr>' + sp + '</w:pPr><w:r>' + RPR_BODY + '<w:t xml:space="preserve">' + esc(text) + '</w:t></w:r></w:p>'


def convertir_en_pdf(docx_path):
    lo = shutil.which("libreoffice") or shutil.which("soffice")
    if not lo:
        logger.warning("LibreOffice non trouvé")
        return None
    try:
        env = os.environ.copy()
        env["HOME"] = str(TEMP_DIR)
        result = subprocess.run(
            [lo, "--headless", "--norestore", "--nologo",
             "--convert-to", "pdf", "--outdir", str(docx_path.parent), str(docx_path)],
            capture_output=True, text=True, timeout=90, env=env
        )
        pdf_path = docx_path.parent / (docx_path.stem + ".pdf")
        if pdf_path.exists():
            logger.info("PDF généré: " + pdf_path.name)
            return pdf_path
        logger.error("PDF non créé: " + result.stderr)
        return None
    except Exception as e:
        logger.error("Erreur LibreOffice: " + str(e))
        return None


